import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0153: ~[n]~> is a dimension index — n-cells as one indexed former","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0153-grades-as-arrow-indices.md","filePath":"vendored/handl/project/adrs/0153-grades-as-arrow-indices.md"}`),a={name:`handl/project/adrs/0153-grades-as-arrow-indices.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0153-n-is-a-dimension-index-—-n-cells-as-one-indexed-former" tabindex="-1">ADR-0153: <code>~[n]~&gt;</code> is a dimension index — n-cells as one indexed former <a class="header-anchor" href="#adr-0153-n-is-a-dimension-index-—-n-cells-as-one-indexed-former" aria-label="Permalink to “ADR-0153: ~[n]~&gt; is a dimension index — n-cells as one indexed former”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-22 (corrects the first draft, which conflated dimensions with coeffect grades)</li><li>Repos: <code>kernel</code> (<code>handl-value</code>, <code>handl-language</code>), <code>kit-prelude-lang</code>, <code>engine-typecheck-nbe</code>, <code>lib-type</code></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><code>A ~[N]~&gt; B</code> parses today as <code>dim_arrow</code> (ADR-0119: &quot;N-dimensional arrow&quot;), <code>&gt;&gt;&gt;[k]</code> is axis-parameterized composition (ADR-0120 Phase 2), and <code>f ~[2]~&gt; g</code> mints n-cell records at runtime. Two readings of the bracket have coexisted: ADR-0106 §10 called it a <em>graded</em> arrow (semiring grades, <code>gradeCompose</code>), while the grammar and <code>&gt;&gt;&gt;[k]</code> machinery treat it as a <em>dimension</em> — the level of the cell being formed. Those are different axes; a coeffect grade (&quot;use twice&quot;) and a cell dimension (&quot;equation between arrows&quot;) are not the same thing and must not share one notation.</p><p><strong>This ADR resolves it: the bracket is the dimension.</strong> <code>~[n]~&gt;</code> forms the type of n-cells — homs at level n. Semiring-style coeffect/usage tracking (QTT quantities, erasure) is a separate, orthogonal axis — deliberately out of the bracket (see §6).</p><p>The literature&#39;s shape applies cleanly once the conflation is removed: indexed families (<code>Vec(n, a)</code>, ADR-0152) already attach type-level data to a former; a cell dimension is the same device applied to the hom former itself.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-n-is-sugar-for-the-dimension-indexed-hom-former" tabindex="-1">1. <code>~[n]~&gt;</code> is sugar for the dimension-indexed hom former <a class="header-anchor" href="#_1-n-is-sugar-for-the-dimension-indexed-hom-former" aria-label="Permalink to “1. ~[n]~&gt; is sugar for the dimension-indexed hom former”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Hom : (n : Dim, src : Cell(n-1), tgt : Cell(n-1)) ~&gt; Type</span></span></code></pre></div><table tabindex="0"><thead><tr><th>surface</th><th>former</th><th>meaning</th></tr></thead><tbody><tr><td><code>A</code></td><td>object</td><td>a 0-cell — an object/type/value</td></tr><tr><td><code>A ~[1]~&gt; B</code> (or <code>A ~&gt; B</code>)</td><td><code>Hom(1, A, B)</code></td><td>a 1-cell — an arrow</td></tr><tr><td><code>f ~[2]~&gt; g</code></td><td><code>Hom(2, f, g)</code></td><td>a 2-cell — an equation/rewrite between arrows</td></tr><tr><td><code>e ~[3]~&gt; e&#39;</code></td><td><code>Hom(3, e, e&#39;)</code></td><td>a 3-cell — an equation between 2-cells</td></tr></tbody></table><p><code>Hom</code> is a nominal former per ADR-0152 §1: <code>Hom(2, f, g)</code> is the canonical application <code>{ &quot;__former__&quot;: homSym, &quot;indices&quot;: [2, f, g] }</code>. Dimensions are <em>indices</em> — type-level data, never present in values — checked by the same machinery as <code>Vec</code>&#39;s <code>n</code>.</p><h3 id="_2-composition-is-k-per-dimension" tabindex="-1">2. Composition is <code>&gt;&gt;&gt;[k]</code>, per dimension <a class="header-anchor" href="#_2-composition-is-k-per-dimension" aria-label="Permalink to “2. Composition is &gt;&gt;&gt;[k], per dimension”">​</a></h3><p><code>f &gt;&gt;&gt;[k] g</code> composes cells along their shared k-boundary — already in the grammar (<code>axis_flow</code>). The n-categorical structure is ordinary declared data: each <code>&gt;&gt;&gt;[k]</code>&#39;s typing rule, identity <code>id_k</code>, and interchange law are stated once for all levels, not baked per dimension:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>e    : f ~[2]~&gt; g</span></span>
<span class="line"><span>eInv : g ~[2]~&gt; f</span></span>
<span class="line"><span>e &gt;&gt;&gt;[2] eInv ~[3]~&gt; id(f)      -- coherence: an equation between 2-cells</span></span></code></pre></div><p><code>Path(a, b)</code> is then definable — an invertible cell is data, not a former:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Path(a,b) := Sigma(e : Hom(2, a, b),</span></span>
<span class="line"><span>             Sigma(eInv : Hom(2, b, a),</span></span>
<span class="line"><span>               Hom(3, e &gt;&gt;&gt;[2] eInv, id(a)) × Hom(3, eInv &gt;&gt;&gt;[2] e, id(b))))</span></span></code></pre></div><h3 id="_3-dimension-polymorphism-is-ordinary-index-binding" tabindex="-1">3. Dimension polymorphism is ordinary index binding <a class="header-anchor" href="#_3-dimension-polymorphism-is-ordinary-index-binding" aria-label="Permalink to “3. Dimension polymorphism is ordinary index binding”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>id&lt;d : Dim&gt;   : A ~[d]~&gt; A</span></span>
<span class="line"><span>comp&lt;d : Dim&gt; : (f ~[d]~&gt; g) ~&gt; (g ~[d]~&gt; h) ~&gt; (f ~[d]~&gt; h)</span></span></code></pre></div><p><code>d</code> is a <code>Pi</code>-bound index — the same mechanism as <code>List&lt;T&gt;</code>&#39;s <code>T</code> (ADR-0106 §8 dimension specialization, finally given semantics). One <code>id</code>/<code>comp</code>/<code>refl</code> serves every cell level — no repeated definitions per dimension.</p><h3 id="_4-effects-are-objects-in-the-codomain-—-never-in-the-bracket" tabindex="-1">4. Effects are objects in the codomain — never in the bracket <a class="header-anchor" href="#_4-effects-are-objects-in-the-codomain-—-never-in-the-bracket" aria-label="Permalink to “4. Effects are objects in the codomain — never in the bracket”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>IO    : Type ~&gt; Type          -- an effect former (or plain object)</span></span>
<span class="line"><span>print : String ~&gt; IO(Unit)    -- a 1-cell producing an effect value</span></span>
<span class="line"><span>echo  := read &gt;&gt;&gt; print       -- ordinary composition</span></span>
<span class="line"><span>handle echo with Console      -- ops interpreted by a handler</span></span></code></pre></div><p>An &quot;effectful arrow&quot; is just an arrow whose target is an effect object; <code>handle ... with</code> interprets it as today. No effect marks in the index — the bracket is reserved for cell dimension.</p><h3 id="_5-usage-erasure-is-a-mode-not-a-dimension-—-out-of-scope-here" tabindex="-1">5. Usage/erasure is a <em>mode</em>, not a dimension — out of scope here <a class="header-anchor" href="#_5-usage-erasure-is-a-mode-not-a-dimension-—-out-of-scope-here" aria-label="Permalink to “5. Usage/erasure is a mode, not a dimension — out of scope here”">​</a></h3><p>QTT-style quantities (erased/typelevel vs runtime) are a different axis again — MTT separates <strong>modes</strong> (which judgment/world a term lives in) from cell structure within a mode. Erasure = membership in the typelevel mode, tracked on the binder/context, orthogonal to <code>~[n]~&gt;</code>. Left to a follow-up ADR; the only commitment made here is that it does <em>not</em> enter the bracket.</p><h3 id="_6-retired-readings" tabindex="-1">6. Retired readings <a class="header-anchor" href="#_6-retired-readings" aria-label="Permalink to “6. Retired readings”">​</a></h3><ul><li>The semiring-grade reading of <code>~[R]~&gt;</code> (ADR-0106 §10, <code>gradeCompose</code> on the bracket) is withdrawn: the bracket forms n-cell types. Usage grades, if pursued, live in the mode axis (§5).</li><li><code>sort</code>/<code>grade</code>/<code>op</code> declaration forms remain, but their graded-arrow interpretation moves to modes; as type-level declarations they elaborate as ordinary formers.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>One indexing mechanism</strong>: <code>Vec(n,a)</code>, <code>Hom(k,f,g)</code>, <code>Arr(r,A,B)</code> (if usage grades are ever added) — every bracket is an index on a nominal former. The checker has one notion to implement.</li><li><strong>Notation coherent</strong>: <code>~[n]~&gt;</code> (the n-cell type) and <code>&gt;&gt;&gt;[k]</code> (the k-composition) now mean the same dimension <code>n</code>/<code>k</code>.</li><li><strong><code>Path</code> decomposes</strong>: invertible equality needs no primitive — Hom <ul><li>inverse + coherence cells, per §2.</li></ul></li><li><strong>Research honesty</strong>: <code>&gt;&gt;&gt;[k]</code> typing rules and interchange laws for general <code>k</code> are implemented for the levels exercised (k ≤ 2); arbitrary-k coherence remains aspirational per ADR-0100&#39;s directed limit — the former shape is dimension-generic, the checked laws are not yet.</li><li><strong>Migration</strong>: <code>~[2]~&gt;</code> surface unchanged; <code>dim_arrow</code>&#39;s payload is read as dimension index rather than grade expression; ADR-0106 §10&#39;s &quot;graded arrows&quot; wording needs a conformance amendment.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li>ADR-0106 §8 (dimensions <code>f&lt;…&gt;</code>), §10 (graded arrows — superseded reading)</li><li>ADR-0119 (<code>~[N]~&gt;</code> surface), ADR-0120 Phase 2 (<code>&gt;&gt;&gt;[k]</code>)</li><li>ADR-0152 (nominal inductive families — the indexing machinery)</li><li>Riehl–Shulman simplicial type theory / Rzk (directed homs); Gratzer–Kavvos–Nuyts–Birkedal, MTT (the mode/grade/dimension split)</li></ul>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};